<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Digital Library | C-Net Library</title><meta name="description" content="Browse public and member digital learning resources from C-Net Library."><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;margin:0;background:#f4f7fa;color:#172033}.nav{background:#fff;border-bottom:1px solid #e2e8f0}.navin{max-width:1160px;margin:auto;padding:15px 20px;display:flex;justify-content:space-between;align-items:center;gap:16px}.brand{font-weight:850;font-size:20px;color:#102a43;text-decoration:none}.wrap{max-width:1160px;margin:28px auto;padding:0 20px}.hero{background:linear-gradient(135deg,#102a43,#0f766e);color:#fff;border-radius:22px;padding:34px;margin-bottom:18px}.hero h1{font-size:38px;margin:0 0 8px}.hero p{color:#d6e6e5;max-width:760px}.account{margin-top:14px;font-size:14px}.filters{background:#fff;border:1px solid #e1e8ef;border-radius:16px;padding:18px;margin-bottom:18px;display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:10px}.filters input,.filters select{padding:11px;border:1px solid #ccd7e1;border-radius:10px;width:100%;background:#fff}.btn{display:inline-flex;align-items:center;justify-content:center;background:#102a43;color:#fff;text-decoration:none;padding:10px 14px;border-radius:10px;border:1px solid #102a43;cursor:pointer;font-weight:750}.btn.alt{background:#fff;color:#102a43;border-color:#ccd7e1}.btn.green{background:#0f766e;border-color:#0f766e}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#fff;border:1px solid #e1e8ef;border-radius:17px;padding:20px;display:flex;flex-direction:column;box-shadow:0 6px 22px rgba(15,23,42,.035)}.card h3{font-size:21px;color:#102a43;margin:10px 0 5px}.badge{display:inline-block;padding:5px 9px;background:#e8f5f2;color:#0f766e;border-radius:999px;font-size:12px;font-weight:800;margin-right:5px}.badge.member{background:#eef2ff;color:#4338